 			continue;

 		for (mt = 0; mt < MIGRATE_PCPTYPES; mt++) {
+			/*
+			 * Under ALLOC_NOFRAGMENT, a request below
+			 * pageblock_order can take another migratetype's page
+			 * only by claiming the whole block.
